import 'package:flutter/material.dart'; import 'package:go_router/go_router.dart'; import '../../../routes/route_paths.dart'; import '../models/chatbot_models.dart';
class PlaceResultCard extends StatelessWidget { const PlaceResultCard({super.key, required this.place, this.onSelect, this.selected = false, this.isClinic = false}); final ChatPlaceResult place; final VoidCallback? onSelect; final bool selected; final bool isClinic; @override Widget build(BuildContext context) { final rtl = Directionality.of(context) == TextDirection.rtl; final name = (rtl ? place.nameAr ?? place.nameEn : place.nameEn ?? place.nameAr) ?? 'Place'; final address = rtl ? place.addressAr ?? place.addressEn : place.addressEn ?? place.addressAr; return Card(color: selected ? Theme.of(context).colorScheme.primaryContainer : null, child: ListTile(selected: selected, onTap: onSelect, title: Text(name), subtitle: Text([?address, ?place.type, if (place.distanceKm != null) '${place.distanceKm!.toStringAsFixed(1)} km'].whereType<String>().join(' · ')), trailing: isClinic && place.id.isNotEmpty ? TextButton(onPressed: () => context.push(RoutePaths.clinicDetailPath(place.id)), child: const Text('Details')) : null)); } }
